import hashlib, json

def idem_key(tool, args, drop=("nonce", "ts")):
    norm = {k: v for k, v in args.items() if k not in drop}
    blob = json.dumps([tool, norm], sort_keys=True, ensure_ascii=False)
    return hashlib.sha256(blob.encode()).hexdigest()[:16]

class ReplayGuard:
    def __init__(self):
        self.seen = {}
    def call(self, tool, args, effect):
        k = idem_key(tool, args)
        if k not in self.seen:
            self.seen[k] = effect()          # 只有第一次真执行，且必须先判键
        return self.seen[k]

g = ReplayGuard()
box = []
for n in ("n1", "n2", "n3"):                # 同一封邮件，三个不同 nonce
    g.call("send_email", {"to": "a@x.com", "nonce": n}, lambda: box.append("sent"))
k1 = idem_key("send_email", {"to": "a@x.com", "subject": "s"})
k2 = idem_key("send_email", {"subject": "s", "to": "a@x.com"})
print("真实副作用:", len(box), "抑制:", 3 - len(box), "键顺序无关:", k1 == k2)

def jaccard(a, b):
    if not a and not b:
        return 1.0
    return len(a & b) / len(a | b)

def d3(obs_seq, k, th=0.9):
    for i in range(k - 1, len(obs_seq)):
        recent = obs_seq[i - k + 1: i + 1]
        if all(jaccard(recent[-1], o) >= th for o in recent[:-1]):
            return i + 1                    # 首次拉闸步号（1 起）
    return None

stall = [{"无相关结果"}] * 6                # 空转：6 步一模一样
retry = [{"a.txt"}, {"a.txt"}, {"ok"}]     # 合法重试：连续 2 步同 observation
for k in (2, 3, 5):
    a, b = d3(stall, k), d3(retry, k)
    print(f"K={k}: 空转轨迹第 {a} 步拉闸；合法重试轨迹 {'第 %d 步误杀' % b if b else '放行'}")

import numpy as np
def ctx_tokens(turns):
    return sum(len(x) // 2 for _, x in turns)
def _facts(head):                        # 只认「订单号」事实，排除追问轮
    return [x for _, x in head if "订单号" in x and "请问" not in x]
def s_sum(t, k=4):
    return [("system", "早期摘要：" + "；".join(_facts(t[:-k])))] + t[-k:]
def s_lossy(t, k=4):                     # 只扫旧轮次最后 4 块：更早事实丢失
    return [("system", "早期摘要：" + "；".join(_facts(t[:-k][-4:])))] + t[-k:]
def evaluate(fn):
    ok = sum(t["order_no"] in " ".join(x for _, x in fn(t["turns"])) for t in tasks)
    return ok / len(tasks), float(np.mean([ctx_tokens(fn(t["turns"])) for t in tasks]))
win = lambda t: t[-4:]
for name, fn in [("全量", lambda t: t), ("窗口k=4", win), ("摘要", s_sum), ("lossy", s_lossy)]:
    acc, tok = evaluate(fn)
    print(f"{name}: 成功率 {acc:.1%}, 平均 {tok:.0f} tok")
